parameters.jsCode:
const webhookData = $('New Submission Webhook').item.json.body;
const claudeResponse = $input.item.json;
const textBlock = (claudeResponse.content || []).find(b => b.type === 'text');
const raw = textBlock ? textBlock.text : '{}';
const match = raw.match(/\{[\s\S]*\}/);
let result = { tier: 'needs_review', reason: 'Could not parse screener response.' };
if (match) {
  try {
    const parsed = JSON.parse(match[0]);
    if (['auto_publish', 'auto_reject', 'needs_review'].includes(parsed.tier)) {
      result = parsed;
    }
  } catch (e) {
    // keep default needs_review
  }
}
return [{ json: { submission_id: webhookData.submission_id, tier: result.tier, reason: result.reason } }];
